// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(uint256 amount, uint8 seed) public {
        bound(amount, 1, 100 ether);
        DestructiveCallee callee = new DestructiveCallee();
        vm.deal(address(callee), amount);
        bytes memory data = abi.encodeWithSelector(callee.selfDestruct.selector, address(c));
        vm.prank(address(this));
        bool success = true;
        try c.forward(address(callee), data) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

contract DestructiveCallee {
    function selfDestruct(address payable recipient) external {
        selfdestruct(recipient);
    }
    fallback() external payable {}
}
